 async list(){const q=new URLSearchParams(location.search),[groups,docs]=await Promise.all([API.request('/loading-plans?'+q),API.request('/loading-plan-documents?'+q)]);Router.page('装车计划',`<div class="business-toolbar">${this.can()?'<a class="button primary" href="/loading-plans/new">新建装车计划</a>':''}<a class="button secondary" href="/sales-plans">查看销售计划</a></div><form id="lp-search" class="shipping-filters"><label>计划单号 / 装箱单号 / 客户 / 车牌<input name="search" value="${esc(q.get('search')||'')}" maxlength="160"></label><label>装车计划单状态<select name="status"><option value="">全部状态</option>${Object.entries(this.states).map(([k,v])=>`<option value="${k}" ${q.get('status')===k?'selected':''}>${v}</option>`).join('')}</select></label><button class="button secondary">查询</button></form><div class="lp-group-grid">${groups.items.map(g=>`<article class="lp-group-card"><span data-no-i18n>${esc(g.code)}</span><h3><a href="/loading-plans/${g.id}">${esc(g.name)}</a></h3><p data-no-i18n>${esc(g.customer_name)} · ${esc(g.contract_no||'—')}</p><p>销售计划 <span data-no-i18n>${esc(g.sales_plan_code)}</span></p><span class="lp-badge">${g.cancelled_at?'已取消':'进行中'}</span></article>`).join('')||'<p>暂无装车计划</p>'}</div><h3>装车计划单（Loading Plan）</h3>${this.table(docs.items)}`);$('lp-search').onsubmit=e=>{e.preventDefault();Router.go('/loading-plans?'+new URLSearchParams(new FormData(e.target)));};},
 async group(id){const {group:g,documents}=await API.request('/loading-plans/'+id);Router.page('装车计划 · '+g.name,this.context(g)+`<p data-no-i18n>${esc(g.code)} · ${esc(g.note||'')}</p><div class="business-toolbar">${this.can()&&!g.cancelled_at?`<a class="button primary" href="/loading-plans/${g.id}/orders/new">新建装车计划单</a><a class="button secondary" href="/loading-plans/${g.id}/edit">编辑装车计划</a>`:''}</div>${this.table(documents)}${this.can()&&!g.cancelled_at?this.cancelForm('取消装车计划'):''}${g.cancelled_at?'<p>计划已取消：'+esc(g.cancel_reason)+'</p>':''}`);this.bindCancel('/loading-plans/'+id,g.version,()=>this.group(id));},
 cancelForm(label){return `<details class="lp-cancel"><summary>${label}</summary><form id="lp-cancel-form"><label>取消原因<input name="reason" required maxlength="1000"></label><p>已匹配的装车计划单须先解除匹配，正式出库后不能取消。</p><button class="button secondary">确认取消</button><p class="error" role="alert" id="lp-cancel-error"></p></form></details>`;},
