const v31LegacyLoadForm=Flow.loadForm.bind(Flow);Flow.loadForm=async()=>{const query=new URLSearchParams(location.search);if(query.has('legacy')||query.has('replaces'))return v31LegacyLoadForm();if(!Business.can('loading-plan:read')||!Business.can('loading-plan:match'))return Router.page('新建装车单','<p class="dialog-notice">新版装车单需要装车计划查看及匹配权限，请联系系统管理员配置。</p><a class="button secondary" href="/outbounds">返回出库管理</a>');return LoadingPlans.loadForm();};
