const v31ShippingDetail=Shipping.detail.bind(Shipping);Shipping.detail=async function(id){await v31ShippingDetail(id);const d=await API.request('/shipping/'+id);if(!d.loading_plan)return;$('business-title').textContent='Packing List · '+d.packing_list_no;const plan=d.loading_plan,panel=document.createElement('section');panel.className='lp-load-summary';panel.innerHTML='<h3>装车计划单信息</h3><p><a href="/loading-plans/orders/'+plan.id+'">查看关联装车计划单</a></p><dl class="lp-fields">'+Object.entries({invoice_no:'发票号',packing_list_no:'装箱单号',export_license_no:'出口许可证号',transporter:'运输商',destination:'目的地',vehicle_no:'车牌号',shipment_batch_no:'批次号',planned_load_date:'计划装车日期'}).map(([key,label])=>'<dt>'+label+'</dt><dd data-no-i18n>'+esc(plan[key]?.slice(0,key==='planned_load_date'?10:1000)||'—')+'</dd>').join('')+'</dl><p>运输信息自动读取关联装车计划单。</p>';$('page-content').prepend(panel);};
const v31Loads=Flow.loads.bind(Flow);Flow.loads=async function(){await v31Loads();const data=await API.request('/shipping/loads?'+new URLSearchParams(location.search)),rows=document.querySelectorAll('#page-content .business-table tbody tr');for(let i=0;i<data.items.length;i++){const l=data.items[i];if(rows[i]&&l.packing_list_no)rows[i].cells[0].innerHTML='<small>装箱单号</small><br><strong data-no-i18n>'+esc(l.packing_list_no)+'</strong>';} };Flow.outbounds=Flow.loads;
Router.names['sales-plans']='销售管理';Router.names['loading-plans']='装车计划';const v31Permission=Router.permission.bind(Router);Router.permission=path=>path.startsWith('/sales-plans')?(/\/(new|edit)$/.test(path)?'plan:write':'plan:read'):path.startsWith('/loading-plans')?(/\/(new|edit)$/.test(path)?'loading-plan:write':'loading-plan:read'):path.endsWith('/matching')?'loading-plan:match':v31Permission(path);
const v31Init=Router.init.bind(Router);Router.init=async function(){this.add(/^\/sales-plans$/,()=>LoadingPlans.sales());this.add(/^\/loading-plans$/,()=>LoadingPlans.list());this.add(/^\/loading-plans\/new$/,()=>LoadingPlans.groupForm());this.add(/^\/loading-plans\/([0-9a-f-]{36})$/,id=>LoadingPlans.group(id));this.add(/^\/loading-plans\/([0-9a-f-]{36})\/edit$/,id=>LoadingPlans.groupForm(id));this.add(/^\/loading-plans\/([0-9a-f-]{36})\/orders\/new$/,group=>LoadingPlans.docForm(group));this.add(/^\/loading-plans\/orders\/([0-9a-f-]{36})$/,id=>LoadingPlans.doc(id));this.add(/^\/loading-plans\/orders\/([0-9a-f-]{36})\/edit$/,id=>LoadingPlans.docForm(null,id));this.add(/^\/outbounds\/loads\/([0-9a-f-]{36})\/matching$/,id=>LoadingPlans.loadForm(id));const r=await v31Init();for(const nav of document.querySelectorAll('.sidebar nav,.mobile-primary')){const out=nav.querySelector('[data-primary-route="outbounds"]');for(const key of ['sales-plans','loading-plans']){const a=nav.querySelector('[data-primary-route="'+key+'"]');if(a&&out)out.before(a);}}return r;};
const v31CSS=document.createElement('link');v31CSS.rel='stylesheet';v31CSS.href='/v31.css';document.head.append(v31CSS);
